### FASE 1: Base de Datos y Configuración

El núcleo de datos para trackear clientes, pagos y el estado de la "forja" del MVP.

**`prisma/schema.prisma`**
```prisma
generator client {
  provider = "prisma-client-js"
}

datasource db {
  provider = "postgresql"
  url      = env("DATABASE_URL")
}

model User {
  id        String   @id @default(cuid())
  email     String   @unique
  name      String?
  projects  Project[]
  createdAt DateTime @default(now())
}

model Project {
  id            String   @id @default(cuid())
  userId        String
  user          User     @relation(fields: [userId], references: [id])
  name          String
  tier          String   // 'landing', 'saas', 'internal_tool'
  businessIdea  String   @db.Text
  status        String   @default("PENDING_PAYMENT") // PENDING_PAYMENT, FORGING, DEPLOYED, COMPLETED
  repoUrl       String?
  liveUrl       String?
  n8nSessionId  String?
  createdAt     DateTime @default(now())
  milestones    Milestone[]
}

model Milestone {
  id        String   @id @default(cuid())
  projectId String
  project   Project  @relation(fields: [projectId], references: [id])
  title     String
  status    String   @default("PENDING") // PENDING, IN_PROGRESS, DONE
  logs      String?  @db.Text
  updatedAt DateTime @updatedAt
}
```

