### FASE 3: API Routes (Next.js App Router)

Los endpoints que conectan el frontend con el motor y reciben los webhooks.

**`app/api/projects/route.ts`** (Creación de proyecto tras pago exitoso)
```typescript
import { NextRequest, NextResponse } from "next/server";
import { forgeProject } from "@/lib/services/orchestrator";
import { prisma } from "@/lib/services/prisma";

export async function POST(req: NextRequest) {
  try {
    const body = await req.json();
    const { userId, name, tier, businessIdea } = body;

    // 1. Crear proyecto en DB (Estado: PENDING_PAYMENT)
    const project = await prisma.project.create({
      data: { userId, name, tier, businessIdea, status: "PENDING_PAYMENT" }
    });

    // 2. Aquí iría la creación de la sesión de Stripe Checkout
    // const session = await stripe.checkout.sessions.create(...)

    // 3. Simulamos que el pago fue exitoso y lanzamos la forja
    // En producción, esto se dispara desde el Webhook de Stripe
    const forgeResult = await forgeProject(project.id);

    return NextResponse.json({ success: true, project, forgeResult }, { status: 201 });
  } catch (error: any) {
    return NextResponse.json({ error: error.message }, { status: 500 });
  }
}
```

**`app/api/webhooks/n8n/route.ts`** (Recibir actualizaciones de la IA/n8n)
```typescript
import { NextRequest, NextResponse } from "next/server";
import { prisma } from "@/lib/services/prisma";

export async function POST(req: NextRequest) {
  const body = await req.json();
  const { sessionId, status, milestone, logs, liveUrl } = body;

  // Buscar proyecto por el ID de sesión de n8n
  const project = await prisma.project.findFirst({
    where: { n8nSessionId: sessionId }
  });

  if (!project) return NextResponse.json({ error: "Not found" }, { status: 404 });

  // Actualizar proyecto
  await prisma.project.update({
    where: { id: project.id },
    data: {
      status: status === 'DONE' ? 'COMPLETED' : 'FORGING',
      liveUrl: liveUrl || project.liveUrl,
      milestones: {
        upsert: {
          where: { title: milestone },
          update: { status: 'DONE', logs },
          create: { title: milestone, status: 'DONE', logs }
        }
      }
    }
  });

  return NextResponse.json({ success: true });
}
```

