"use client";
import { useState } from "react";

export default function ScopingWizard() {
  const [step, setStep] = useState(1);
  const [data, setData] = useState({ name: "", tier: "saas", idea: "" });

  const handleSubmit = async () => {
    // Llamada a la API para crear proyecto y procesar pago
    await fetch("/api/projects", {
      method: "POST",
      body: JSON.stringify({ ...data, userId: "user_123" })
    });
    alert("¡Pago procesado! Tu MVP está en la forja.");
  };

  return (
    <div className="max-w-2xl mx-auto p-8 bg-zinc-900 text-white rounded-2xl border border-zinc-800">
      <h2 className="text-3xl font-bold mb-6 bg-gradient-to-r from-blue-400 to-purple-500 text-transparent bg-clip-text">
        Zero-Day Launchpad
      </h2>

      {step === 1 && (
        <div className="space-y-4">
          <label className="block text-sm font-medium">Nombre del Proyecto</label>
          <input 
            className="w-full p-3 bg-zinc-800 rounded-lg border border-zinc-700 focus:border-blue-500 outline-none"
            onChange={(e) => setData({...data, name: e.target.value})} 
          />
          <button onClick={() => setStep(2)} className="w-full py-3 bg-blue-600 hover:bg-blue-700 rounded-lg font-semibold">Siguiente</button>
        </div>
      )}

      {step === 2 && (
        <div className="space-y-4">
          <label className="block text-sm font-medium">Describe tu Idea de Negocio</label>
          <textarea 
            rows={5}
            className="w-full p-3 bg-zinc-800 rounded-lg border border-zinc-700 focus:border-blue-500 outline-none"
            placeholder="Ej: Un SaaS de gestión de inventario para farmacias independientes..."
            onChange={(e) => setData({...data, idea: e.target.value})}
          />
          <button onClick={handleSubmit} className="w-full py-3 bg-gradient-to-r from-blue-600 to-purple-600 hover:opacity-90 rounded-lg font-semibold">
            Pagar $4,500 y Forjar MVP (72h)
          </button>
        </div>
      )}
    </div>
  );
}
```

**`components/ForgeTracker.tsx`**
```tsx
"use client";
import { useEffect, useState } from "react";

export default function ForgeTracker({ projectId }: { projectId: string }) {
  const [project, setProject] = useState<any>(null);

  useEffect(() => {
    // Polling cada 5 segundos para actualizar el estado en tiempo real
    const interval = setInterval(async () => {
      const res = await fetch(`/api/projects/${projectId}`);
      const data = await res.json();
      setProject(data);
    }, 5000);
    return () => clearInterval(interval);
  }, [projectId]);

  if (!project) return <div className="text-zinc-400">Cargando estado de la forja...</div>;

  return (
    <div className="p-6 bg-zinc-900 rounded-xl border border-zinc-800">
      <div className="flex justify-between items-center mb-6">
        <h3 className="text-xl font-bold text-white">{project.name}</h3>
        <span className={`px-3 py-1 rounded-full text-xs font-bold ${
          project.status === 'COMPLETED' ? 'bg-green-900 text-green-300' : 'bg-blue-900 text-blue-300 animate-pulse'
        }`}>
          {project.status === 'COMPLETED' ? '✅ DESPLEGADO' : '🔥 FORJANDO...'}
        </span>
      </div>

      <div className="space-y-3">
        {project.milestones?.map((m: any) => (
          <div key={m.id} className="flex items-center p-3 bg-zinc-800 rounded-lg">
            <div className={`w-3 h-3 rounded-full mr-3 ${m.status === 'DONE' ? 'bg-green-500' : 'bg-zinc-600'}`}></div>
            <span className="text-zinc-300">{m.title}</span>
          </div>
        ))}
      </div>

      {project.liveUrl && (
        <a href={project.liveUrl} target="_blank" className="mt-6 block text-center py-3 bg-green-600 hover:bg-green-700 rounded-lg font-semibold text-white">
          Ver MVP en Producción 🚀
        </a>
      )}
    </div>
  );
}
```

